export const CANONICAL_SHORT_NAMES={"Kurg": "William", "Aeric": "Walter", "Rhoswen": "Matilda", "Aldren": "Yusuf", "Yselle": "Aisha", "Corvin": "Ahmad", "Samiel": "Ismail", "Braska": "Khalid", "Mirelle": "Fatima", "Lucain": "Hasan", "Oren": "Ibrahim", "Beric": "Geoffrey", "Elsen": "Roger", "Maela": "Matilda", "Rell": "Walter", "Varo": "Ralph", "Veyr": "Hugh FitzAlan", "Ossael": "Umar ibn Musa", "Mordren": "Robert de Brienne", "Caelor": "Ahmad ibn Umar", "Mirra": "Maryam bint Salim", "Velcar": "Henry FitzGeoffrey", "Nema": "Khadija bint Yusuf"};
export function canonicalCharacterName(id,fallback){return CANONICAL_CHARACTER_RENAMES.find(r=>r.character_id===id)?.new||fallback;}
export function canonicalText(text){if(typeof text!=='string')return text;for(const r of CANONICAL_CHARACTER_RENAMES)text=text.replaceAll(r.old,r.new);text=text.replaceAll('Severin Vale','Severin de Beaumont').replaceAll('Pateric','Peter').replaceAll('Traden','Thomas');for(const [old,name]of Object.entries(CANONICAL_SHORT_NAMES))text=text.replace(new RegExp('\\b'+old+'\\b','g'),name);return text;}
export function migrateCanonicalBattle(battle){if(battle?.trainer){battle.trainer.name=canonicalCharacterName(battle.trainer.id,battle.trainer.name);}return battle;}
export function canonicalDialogueTree(value){if(Array.isArray(value))return value.map(canonicalDialogueTree);if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([key,v])=>[key,['text','name','speaker','before','after','repeat','description'].includes(key)&&typeof v==='string'?canonicalText(v):v&&typeof v==='object'?canonicalDialogueTree(v):v]));return value;}
